def solve(inputs: dict) -> float:
    # Parse input
    M = inputs['M']
    n = inputs['n']
    mod = inputs['mod']

    # Matrix multiplication with modulo
    def matrix_mult(A, B, mod):
        result = [[0, 0], [0, 0]]
        for i in range(2):
            for j in range(2):
                for k in range(2):
                    result[i][j] = (result[i][j] + A[i][k] * B[k][j]) % mod
        return result

    # Matrix exponentiation by squaring
    def matrix_pow(M, exp, mod):
        # Start with identity matrix
        result = [[1, 0], [0, 1]]
        base = [row[:] for row in M]  # Copy M

        while exp > 0:
            if exp % 2 == 1:
                result = matrix_mult(result, base, mod)
            base = matrix_mult(base, base, mod)
            exp //= 2

        return result

    # Compute M^n mod mod
    result = matrix_pow(M, n, mod)

    # Sum all entries
    total = sum(sum(row) for row in result)

    return float(total % mod)

